"use client";

import { AnimatePresence, motion, useReducedMotion, type Transition } from "motion/react";
import { type ChangeEvent, type ComponentPropsWithoutRef, type ReactNode, useId, useLayoutEffect, useRef, useState } from "react";

import { cn } from "@/lib/utils";

/** What the three fields hold: `number` as digits only, `expiry` as the person sees it ("MM/YY"), `csc` as digits. */
export type CardValue = { number: string; expiry: string; csc: string };

/** Props for the card fields. Pass `value` to control them, or `defaultValue` to let them hold their own state. */
export type CardNumberFieldProps = Omit<ComponentPropsWithoutRef<"fieldset">, "onChange" | "children" | "defaultValue"> & {
  value?: CardValue;
  defaultValue?: CardValue;
  onValueChange?: (value: CardValue) => void;
  /** Names the group of three fields. */
  legend?: ReactNode;
};

const EMPTY: CardValue = { number: "", expiry: "", csc: "" };
// The longest card number in use has 19 digits.
const MAX_DIGITS = 19;
const GROUP = 4;
const SLIDE: Transition = { duration: 0.2, ease: [0.165, 0.84, 0.44, 1] };

const digitsOf = (text: string) => text.replace(/\D/g, "");
const groupsOf = (digits: string) => digits.match(/\d{1,4}/g) ?? [];

function formatExpiry(text: string) {
  let digits = digitsOf(text).slice(0, 4);
  // No month starts with 2 to 9, so a first digit above 1 is a whole month.
  if (digits.length === 1 && digits > "1") digits = `0${digits}`;
  return digits.length > 2 ? `${digits.slice(0, 2)}/${digits.slice(2)}` : digits;
}

// The mono face gives the input and the layer drawn over it the same glyph widths.
// 16px text on a phone stops iOS from zooming into the field.
const TEXT = "font-mono text-base tabular-nums sm:text-sm";
const FIELD = cn(
  TEXT,
  "h-11 w-full rounded-lg border border-border bg-background px-3 text-foreground outline-none placeholder:text-muted-foreground focus-visible:ring-2 focus-visible:ring-ring",
);

/**
 * Three fields for paying by card: the number, the expiry date and the security code. The number groups its
 * digits in fours while the person types, and each new group slides in. Spaces, dashes and pasted text are
 * accepted and cleaned. It checks nothing about the card: validate it where you charge it.
 */
export function CardNumberField({
  value,
  defaultValue = EMPTY,
  onValueChange,
  legend = "Card details",
  className,
  disabled,
  ...fieldsetProps
}: CardNumberFieldProps) {
  const [ownValue, setOwnValue] = useState(defaultValue);
  const numberInput = useRef<HTMLInputElement>(null);
  // Where the caret belongs after the number is regrouped. Without it, an edit in the middle throws the caret to the end.
  const caret = useRef<number | null>(null);
  const id = useId();
  const reduceMotion = useReducedMotion();
  const card = value ?? ownValue;
  const groups = groupsOf(card.number);

  useLayoutEffect(() => {
    if (caret.current === null) return;
    numberInput.current?.setSelectionRange(caret.current, caret.current);
    caret.current = null;
  });

  const commit = (change: Partial<CardValue>) => {
    const next = { ...card, ...change };
    if (value === undefined) setOwnValue(next);
    onValueChange?.(next);
  };

  const changeNumber = (event: ChangeEvent<HTMLInputElement>) => {
    const typed = event.target.value;
    const digits = digitsOf(typed).slice(0, MAX_DIGITS);
    const before = Math.min(digits.length, digitsOf(typed.slice(0, event.target.selectionStart ?? typed.length)).length);
    // One space sits in front of every group but the first.
    caret.current = before + Math.floor(Math.max(0, before - 1) / GROUP);
    commit({ number: digits });
  };

  return (
    <fieldset {...fieldsetProps} disabled={disabled} className={cn("grid w-full min-w-0 grid-cols-2 gap-x-2 gap-y-3 text-sm disabled:opacity-50", className)}>
      <legend className="mb-3 font-medium text-foreground">{legend}</legend>
      <div className="col-span-2 flex min-w-0 flex-col gap-1.5">
        <label htmlFor={`${id}-number`} className="text-muted-foreground">
          Card number
        </label>
        <div className="relative">
          <input
            ref={numberInput}
            id={`${id}-number`}
            name="cc-number"
            type="text"
            inputMode="numeric"
            autoComplete="cc-number"
            spellCheck={false}
            placeholder="0000 0000 0000 0000"
            value={groups.join(" ")}
            onChange={changeNumber}
            // The digits are drawn by the layer below, so the input's own text is clear and only its caret shows.
            className={cn(FIELD, "text-transparent caret-foreground")}
          />
          <span aria-hidden="true" className={cn(TEXT, "pointer-events-none absolute inset-px flex items-center overflow-hidden whitespace-pre px-3 text-foreground")}>
            <AnimatePresence initial={false}>
              {groups.map((group, index) => (
                <motion.span
                  key={index}
                  initial={reduceMotion ? false : { opacity: 0, x: 8 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={SLIDE}
                  className="inline-block"
                >
                  {index > 0 ? ` ${group}` : group}
                </motion.span>
              ))}
            </AnimatePresence>
          </span>
        </div>
      </div>
      <div className="flex min-w-0 flex-col gap-1.5">
        <label htmlFor={`${id}-expiry`} className="text-muted-foreground">
          Expiry
        </label>
        <input
          id={`${id}-expiry`}
          name="cc-exp"
          type="text"
          inputMode="numeric"
          autoComplete="cc-exp"
          spellCheck={false}
          placeholder="MM/YY"
          value={card.expiry}
          onChange={(event) => commit({ expiry: formatExpiry(event.target.value) })}
          className={FIELD}
        />
      </div>
      <div className="flex min-w-0 flex-col gap-1.5">
        <label htmlFor={`${id}-csc`} className="whitespace-nowrap text-muted-foreground">
          Security code
        </label>
        <input
          id={`${id}-csc`}
          name="cc-csc"
          type="text"
          inputMode="numeric"
          autoComplete="cc-csc"
          spellCheck={false}
          placeholder="123"
          value={card.csc}
          onChange={(event) => commit({ csc: digitsOf(event.target.value).slice(0, 4) })}
          className={FIELD}
        />
      </div>
    </fieldset>
  );
}
